    public static boolean systemTagIsExcluded(String tagFormat) {
        for (String excludedTagFormat : excludedTagFormats) {
            if (Objects.equals(excludedTagFormat, tagFormat)) {
                return true;
            }
        }
        return false;
    }

    public static boolean resourceConfigIsExcluded(String targetIdentity) {
        for (String excludedGlobalConfigIdentity : excludedGlobalConfigIdentities) {
            if (Objects.equals(excludedGlobalConfigIdentity, targetIdentity)) {
                return true;
            }
        }
        return false;
    }
